// Auto-generated by the per-command split.
const os = require('os');
const dns = require('dns').promises;
const tls = require('tls');
const crypto = require('crypto');
const moment = require('moment-timezone');
const fetch = require('node-fetch');
const ytSearch = require('yt-search');
const { formatUptime, formatUptimeVerbose, extractNumber, progressBar } = require('../lib/helpers');

// NOTE: uses ctx.allCommands (full command list), supplied by index.js

function buildCommand() {
  const __args = [['menu', 'help'], 'Owner', 'Show the full command menu', async (ctx) => {
  const { sock, from, msg, settings, cfg, senderNumber } = ctx;
  const loadingMsg = await sock.sendMessage(from, { text: `⚡ *${cfg.botName} menu loading...*` }, { quoted: msg });

  const bySection = {};
  for (const c of ctx.allCommands) {
    if (!bySection[c.section]) bySection[c.section] = [];
    bySection[c.section].push(c.commands[0]);
  }

  const totalMemMB = os.totalmem() / 1024 / 1024;
  const usedMemMB = totalMemMB - os.freemem() / 1024 / 1024;
  const ramPercent = Math.round((usedMemMB / totalMemMB) * 100);
  const platformName = os.platform() === 'linux' ? 'Linux' : os.platform() === 'android' ? 'Android' : os.platform();
  const packageVersion = require('../package.json').version;

  let header = `┌─「 *${cfg.botName}* 」\n`;
  header += `│ User: ${senderNumber}\n`;
  header += `│ Owner: ${settings.owner || cfg.ownerNumber || 'Not set'}\n`;
  header += `│ Contact Developer: ${cfg.masterNumbers[0] || 'Not set'}\n`;
  header += `│ Mode: ${settings.mode || 'Public'}\n`;
  header += `│ Prefix: [${settings.prefix || cfg.prefix}]\n`;
  header += `│ Version: ${packageVersion}\n`;
  header += `│ Platform: ${platformName}\n`;
  header += `│ Status: Active\n`;
  header += `│ Timezone: Africa/Lagos\n`;
  header += `│ Uptime: ${formatUptime(process.uptime())}\n`;
  header += `│ RAM: ${progressBar(ramPercent)} ${ramPercent}%\n`;
  header += `│ Memory: ${usedMemMB.toFixed(1)}MB / ${totalMemMB.toFixed(1)}MB\n`;
  header += `└─────────────────\n`;

  let menuText = header;
  for (const [section, cmds] of Object.entries(bySection)) {
    menuText += `\n*── ${section.toUpperCase()} ──*\n${cmds.map(c => (settings.prefix || cfg.prefix) + c).join(', ')}\n`;
  }
  menuText += `\n_${moment().tz('Africa/Lagos').format('dddd, DD MMM YYYY - HH:mm')}_`;

  try { await sock.sendMessage(from, { delete: loadingMsg.key }); } catch (e) {}

  const imageUrl = settings.menuImageUrl || cfg.menuImageUrl;
  if (imageUrl) {
    await sock.sendMessage(from, { image: { url: imageUrl }, caption: menuText });
  } else {
    await sock.sendMessage(from, { text: menuText });
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
